"""Standalone blind human graph editor; candidates never auto-fill the gold graph."""
import argparse,json,html
from pathlib import Path

def main():
 p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(exist_ok=True,parents=True);inputs=json.load(open(a.run/'data/public_inputs.json'));pred={}
 for tag in 'ABCD':
  path=a.run/tag/'predictions.jsonl'
  if path.exists():pred[tag]={str(x['index']):x for x in map(json.loads,path.read_text().splitlines())}
 payload=json.dumps(dict(inputs=inputs,predictions=pred),ensure_ascii=False).replace('</','<\\/')
 page='''<!doctype html><meta charset="utf-8"><title>CityNav指令关系图盲核验</title><style>body{font:16px sans-serif;max-width:1300px;margin:25px auto;padding:10px;background:#f7f8fa}button,select,input{font:inherit;padding:7px;margin:3px}article{background:white;padding:20px;margin:12px 0;border:1px solid #ddd}textarea{width:98%;min-height:280px;font:14px monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere}.target{background:#b5e7ca}.landmark{background:#ffe1a8}.intermediate{background:#c5dcff}#source{font-size:21px;line-height:1.7}#status{color:#215b3c}</style>
<h1>CityNav语言关系图核验（TRAIN）</h1><p>先仅看原文，独立填写关系图。候选默认隐藏；查看候选后保存的标注属于辅助审核，不能自动充当独立金标准。页面不显示目标坐标、轨迹或方向误差。</p>
<button id="prev">上一条</button><button id="next">下一条</button><button id="unreviewed">下一条未核验</button><select id="select"></select><span id="progress"></span>
<article><h2 id="title"></h2><div id="source"></div><details><summary>公开地标名称目录</summary><p id="catalog"></p></details></article>
<article><h2>人工关系图</h2><p>实体start/end采用原文字符偏移；role为target、landmark、intermediate或reference。关系保留主客体，方向参考系不明确时标未知。不必强行连成完整链。</p><input id="reviewer" placeholder="审核人代号（必填）"><label><input id="complete" type="checkbox">已完成独立检查</label><p>在上方英文中选中文字，再添加实体：</p><select id="entityrole"><option>target</option><option>landmark</option><option>intermediate</option><option>reference</option></select><select id="entitytype"><option>building</option><option>car</option><option>parking</option><option>road</option><option>ground</option><option>other</option></select><button id="addentity">添加选中实体</button><p>添加有向关系：<select id="subject"></select><input id="relation" placeholder="关系词，如inside、next to"><select id="object"></select><button id="addrelation">添加关系</button></p><textarea id="editor" aria-label="人工关系图JSON"></textarea><p>错误类型：</p><div id="reasons"></div><input id="note" style="width:80%" placeholder="备注/歧义"><p><button id="save">保存标注</button><button id="export">导出JSON</button><button id="exportcsv">导出CSV</button><input id="import" type="file" accept="application/json"></p><div id="status"></div></article>
<article><button id="reveal">查看模型候选（之后保存将标记为辅助审核）</button><section id="candidates" hidden><select id="parser"><option>A</option><option>B</option><option>C</option><option>D</option></select><div id="highlight"></div><pre id="candidate"></pre></section></article>
<script id="payload" type="application/json">PAYLOAD</script><script>
const D=JSON.parse(document.getElementById('payload').textContent),$=x=>document.getElementById(x),KEY='citynav-parser-review-v1-'+D.inputs.map(x=>x.index).join(','),store=JSON.parse(localStorage.getItem(KEY)||'{}');let pos=0,seen=false;
const reasons=['目标遗漏','地标遗漏','中间实体遗漏','关系方向反转','错误作用域','直接/间接误判','文本无法唯一确定方位','其他'];$('reasons').innerHTML=reasons.map((r,i)=>`<label><input type="checkbox" data-reason="${r}">${r}</label>`).join(' ');
D.inputs.forEach((r,i)=>{let e=document.createElement('option');e.value=i;e.textContent=(i+1)+' / '+r.index;$('select').appendChild(e)});
function draft(){return {target_description:'',entities:[],relations:[],ambiguities:[]}}
function updateEndpoints(){try{let g=JSON.parse($('editor').value);for(let key of ['subject','object']){$(key).replaceChildren();for(let e of g.entities){let op=document.createElement('option');op.value=e.id;op.textContent=e.id+': '+e.text;$(key).append(op)}}}catch(err){}}
$('editor').oninput=updateEndpoints;
$('addentity').onclick=()=>{try{let sel=window.getSelection();if(!sel.rangeCount)throw Error('请先选中原文中的文字');let range=sel.getRangeAt(0),source=$('source');if(!source.contains(range.commonAncestorContainer))throw Error('只能选择原始英文');let pre=range.cloneRange();pre.selectNodeContents(source);pre.setEnd(range.startContainer,range.startOffset);let start=pre.toString().length,text=range.toString();if(!text)throw Error('未选择文字');let g=JSON.parse($('editor').value),e={id:'human_'+g.entities.length,text,start,end:start+text.length,role:$('entityrole').value,type:$('entitytype').value};g.entities.push(e);if(e.role==='target'&&!g.target_description)g.target_description=text;$('editor').value=JSON.stringify(g,null,2);updateEndpoints();$('status').textContent='已添加实体，请保存'}catch(e){$('status').textContent=e.message}};
$('addrelation').onclick=()=>{try{let g=JSON.parse($('editor').value),subject=$('subject').value,object=$('object').value,relation=$('relation').value.trim();if(!subject||!object||subject===object||!relation)throw Error('请指定两个不同实体及关系词');g.relations.push({subject,relation,object,reference_frame:'unspecified'});$('editor').value=JSON.stringify(g,null,2)}catch(e){$('status').textContent=e.message}};
function persist(){localStorage.setItem(KEY,JSON.stringify(store));$('progress').textContent=Object.values(store).filter(x=>x.reviewed).length+'/'+D.inputs.length+'已核验'}
function load(){let r=D.inputs[pos],v=store[r.index];seen=!!v?.candidate_viewed;$('title').textContent='Task '+r.index;$('source').textContent=r.text;$('catalog').textContent=r.landmark_catalog.join(' · ');$('select').value=pos;$('editor').value=JSON.stringify(v?.graph||draft(),null,2);$('note').value=v?.note||'';$('reviewer').value=v?.reviewer||localStorage.getItem('parser-reviewer')||'';$('complete').checked=!!v?.reviewed;document.querySelectorAll('[data-reason]').forEach(x=>x.checked=(v?.reasons||[]).includes(x.dataset.reason));$('candidates').hidden=true;updateEndpoints();$('status').textContent=v?'已恢复标注；'+(v.independent?'独立盲审核':'辅助/未完成审核'):'';persist()}
function candidate(){let r=D.inputs[pos],v=D.predictions[$('parser').value]?.[r.index];$('candidate').textContent=v?JSON.stringify(v.graph,null,2):'此解析器尚无结果';$('highlight').textContent=r.text;let spans=(v?.graph?.entities||[]).filter(x=>x.start>=0&&x.end<=r.text.length).sort((a,b)=>a.start-b.start);let frag=document.createDocumentFragment(),last=0;for(let s of spans){if(s.start<last)continue;frag.append(document.createTextNode(r.text.slice(last,s.start)));let e=document.createElement('mark');e.className=s.role;e.textContent=r.text.slice(s.start,s.end);e.title=s.role;frag.append(e);last=s.end}frag.append(document.createTextNode(r.text.slice(last)));$('highlight').replaceChildren(frag)}
$('reveal').onclick=()=>{seen=true;$('candidates').hidden=false;candidate();let id=D.inputs[pos].index;store[id]={...(store[id]||{}),index:id,candidate_viewed:true};persist()};$('parser').onchange=candidate;
$('save').onclick=()=>{try{let r=D.inputs[pos],graph=JSON.parse($('editor').value),reviewer=$('reviewer').value.trim();if(!reviewer)throw Error('请填写审核人代号');if(!Array.isArray(graph.entities)||!Array.isArray(graph.relations))throw Error('需要entities和relations数组');let ids=new Set;for(let e of graph.entities){if(r.text.slice(e.start,e.end)!==e.text||ids.has(e.id)||!['target','landmark','intermediate','reference'].includes(e.role))throw Error('实体跨度、ID或role无效');ids.add(e.id)}for(let e of graph.relations)if(!ids.has(e.subject)||!ids.has(e.object))throw Error('关系引用不存在的实体ID');store[r.index]={index:r.index,text:r.text,graph,reviewer,reviewed:$('complete').checked,independent:!seen,candidate_viewed:seen,note:$('note').value,reasons:[...document.querySelectorAll('[data-reason]:checked')].map(x=>x.dataset.reason),review_time:new Date().toISOString(),source:'human_editor',schema_version:1};localStorage.setItem('parser-reviewer',reviewer);persist();$('status').textContent='保存成功：'+(!seen?'独立盲审核':'辅助审核（不计入独立金标准）')}catch(e){$('status').textContent=e.message}};
function download(text,name,type){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('export').onclick=()=>download(JSON.stringify(Object.values(store),null,2),'human_graph_reviews.json','application/json');$('exportcsv').onclick=()=>{let head=['index','reviewer','reviewed','independent','reasons','note','graph'];let q=x=>'"'+String(x??'').replaceAll('"','""')+'"';download([head.join(','),...Object.values(store).map(r=>head.map(k=>q(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])).join(','))].join('\\n'),'human_graph_reviews.csv','text/csv')};
$('import').onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());if(!Array.isArray(v))throw Error('必须是JSON数组');for(let r of v){let source=D.inputs.find(x=>x.index===r.index);if(!source||source.text!==r.text)throw Error('任务原文不匹配');store[r.index]=r}persist();load()}catch(err){$('status').textContent=err.message}};
$('prev').onclick=()=>{pos=(pos-1+D.inputs.length)%D.inputs.length;load()};$('next').onclick=()=>{pos=(pos+1)%D.inputs.length;load()};$('unreviewed').onclick=()=>{for(let i=1;i<=D.inputs.length;i++){let p=(pos+i)%D.inputs.length;if(!store[D.inputs[p].index]?.reviewed){pos=p;load();return}}};$('select').onchange=e=>{pos=+e.target.value;load()};load();
</script>'''.replace('PAYLOAD',payload)
 (a.output/'review.html').write_text(page)
if __name__=='__main__':main()
